        weak var plan: ColdEraseSchema2RatingPlanV1? = nil
        let adapter: PreferencesAdapterV1
        var issued: Bool = false
        var uncertainPlan: ColdEraseSchema2RatingPlanV1? = nil
        let byteCount: UInt64
