                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try scratchCleanupScope.requireHeld(operation: self, store: store,
                registry: registry, exclusion: exclusion, activity: activity)
        } else {
            try exclusion.revalidate()
        }
