#if DEBUG
                        self.recordOriginalScratchLoanDiagnosticStep(.initialImageBinding)
#endif
                        try permit.requireInitialImage(initial)
#if DEBUG
                        self.recordOriginalScratchLoanDiagnosticStep(.ledgerStaticEntry)
#endif
