    func beginOriginalEraseWriterTransition(
        registry: GenerationLeaseRegistryV1,
        oldWriter: GenerationLeaseHandleV1,
        targetAllocation: GenerationWriterAllocationAttemptV1,
        coordinator: StoreSessionCoordinator
